from flask import Flask, request, jsonify
from typing import Dict, List
import datetime

app = Flask(__name__)

# In-memory storage for books
books: Dict[int, dict] = {}
current_id = 1

@app.route('/api/books', methods=['GET', 'POST'])
def manage_books():
    global current_id

    if request.method == 'POST':
        data = request.get_json()

        # Validate required fields
        required_fields = ['title', 'author', 'publication_year']
        if not all(field in data for field in required_fields):
            return jsonify({
                'error': 'Missing required fields',
                'required_fields': required_fields
            }), 400

        # Validate publication year
        try:
            year = int(data['publication_year'])
            current_year = datetime.datetime.now().year
            if year < 1000 or year > current_year:
                return jsonify({
                    'error': f'Publication year must be between 1000 and {current_year}'
                }), 400
        except ValueError:
            return jsonify({
                'error': 'Publication year must be a valid integer'
            }), 400

        # Create new book entry
        new_book = {
            'id': current_id,
            'title': data['title'],
            'author': data['author'],
            'publication_year': year
        }
        books[current_id] = new_book
        current_id += 1

        return jsonify(new_book), 201

    else:  # GET request
        # Check for year filter
        year_filter = request.args.get('year', type=int)

        if year_filter:
            filtered_books = [
                book for book in books.values()
                if book['publication_year'] == year_filter
            ]
            return jsonify(filtered_books)

        return jsonify(list(books.values()))

if __name__ == '__main__':
    # Add some sample data
    books[current_id] = {
        'id': current_id,
        'title': 'Sample Book',
        'author': 'John Doe',
        'publication_year': 2023
    }
    current_id += 1

    app.run(debug=True)
